	private static String toSparqlString(ConjunctiveFilterExpr filterExpr, RemoteCapabilities capabilities)
			throws FilterConversionException {

		StringBuilder sb = new StringBuilder();
		int count = 0;
		sb.append("( ");
		for (FilterExpr expr : filterExpr.getExpressions()) {
			append(expr.getExpression(), sb, capabilities);
			if (++count < filterExpr.getExpressions().size()) {
				sb.append(" && ");
			}
		}
		sb.append(" )");

		return sb.toString();
	}

